// (self-inflicted .git/shallow, regressions #1443/#1276) or stamping promisor
// config onto the named [remote "origin"] section (regression #934). The
// .git/config guard baselined by the clone helpers fails at cleanup if origin
// gains promisor pollution beyond what git itself wrote at clone time.

// cloneShallowFrom makes a real `git clone --depth=1` of bareDir over the smart
// file:// transport (required for --depth to be honored from a local bare).
func cloneShallowFrom(t *testing.T, env *TestEnv, bareDir string) *TestEnv {
	t.Helper()
	return env.cloneFromWithArgs("file://"+bareDir,
		[]string{"-c", "protocol.file.allow=always", "--depth=1"})
}

// clonePartialFrom makes a real `git clone --filter=blob:none` of bareDir over
// the smart file:// transport. enableFilterOnBare turns on uploadpack.allowFilter
// so the server honors the filter (git writes promisor config onto origin at
// clone time — the guard tolerates that baseline and only catches later CLI
// pollution).
func clonePartialFrom(t *testing.T, env *TestEnv, bareDir string) *TestEnv {
	t.Helper()
	enableFilterOnBare(t, bareDir, testutil.GitIsolatedEnv())
	return env.cloneFromWithArgs("file://"+bareDir,
		[]string{"-c", "protocol.file.allow=always", "--filter=blob:none"})
}

// isShallowRepo reports whether the repo at dir is shallow (has a .git/shallow
// graft). Uses git's own answer rather than probing the file so a linked
// worktree resolves correctly.
func isShallowRepo(t *testing.T, dir string) bool {
	t.Helper()
	cmd := exec.CommandContext(t.Context(), "git", "rev-parse", "--is-shallow-repository")
	cmd.Dir = dir
	cmd.Env = testutil.GitIsolatedEnv()
// CloneFrom clones from a bare repo into a new temp directory and returns a new TestEnv
// pointing at the clone. The clone has its own .entire directory initialized.
// The clone checks out the same branch as the current env's HEAD.
func (env *TestEnv) CloneFrom(bareDir string) *TestEnv {
	env.T.Helper()
	return env.cloneFromWithArgs(bareDir, nil)
}

// cloneFromWithArgs is CloneFrom with an explicit clone source and extra `git
// clone` flags/config, so callers can produce shallow (--depth) or partial
// (--filter=blob:none) user clones. cloneSource may be a local path or a
// file:// URL; extraArgs are inserted before the source (e.g. "-c",
// "protocol.file.allow=always", "--filter=blob:none"). The resulting TestEnv is
// otherwise identical to CloneFrom's (own .entire, git config guard baselined).
func (env *TestEnv) cloneFromWithArgs(cloneSource string, extraArgs []string) *TestEnv {
	env.T.Helper()

	ctx := env.T.Context()

	cloneDir := env.T.TempDir()
	if resolved, err := filepath.EvalSymlinks(cloneDir); err == nil {
		cloneDir = resolved
	}

	// Get the current branch name to clone the right branch
	currentBranch := env.GetCurrentBranch()

	// Clone the bare repo, explicitly checking out the right branch.
	// Bare repos may have HEAD pointing to a non-existent default branch
	// when the original was on a feature branch.
	cloneArgs := []string{"clone"}
	cloneArgs = append(cloneArgs, extraArgs...)
	if currentBranch != "" {
		cloneArgs = append(cloneArgs, "--branch", currentBranch)
	}
	cloneArgs = append(cloneArgs, cloneSource, cloneDir)
	cmd := exec.CommandContext(ctx, "git", cloneArgs...)
	cmd.Env = testutil.GitIsolatedEnv()
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("failed to clone from %s: %v\n%s", cloneSource, err, output)
	}

	// Configure git user (clone doesn't inherit local config from the bare repo)
	for _, kv := range [][2]string{
		{"user.name", "Test User"},
		{"user.email", "test@example.com"},
		{"commit.gpgsign", "false"},
	} {
		cmd = exec.CommandContext(ctx, "git", "config", kv[0], kv[1])
		cmd.Dir = cloneDir
		cmd.Env = testutil.GitIsolatedEnv()

